export default function dates({ propertyId, recipient, chatId }) {
  if (
    !/^\d+$/.test(propertyId) ||
    typeof recipient !== "string" ||
    !/^\S+@\S+\.\S+$/.test(recipient) ||
    typeof chatId !== "string" ||
    !chatId ||
    chatId.startsWith("YOUR_")
  )
    throw Error("Configure property, email and Telegram chat");
  const today = new Date(),
    iso = (d) => d.toISOString().slice(0, 10),
    end = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate() - 1)),
    start = new Date(end.getTime() - 6 * 86400000),
    year = (d) => {
      let x = new Date(d);
      x.setUTCFullYear(x.getUTCFullYear() - 1);
      return x;
    };
  const priorEnd = year(end),
    priorStart = new Date(priorEnd.getTime() - 6 * 86400000);
  return {
    propertyId,
    recipient,
    chatId,
    recentStart: iso(start),
    recentEnd: iso(end),
    previousStart: iso(priorStart),
    previousEnd: iso(priorEnd),
  };
}

