export default async function collect(
  { propertyId, recentStart, recentEnd, previousStart, previousEnd, previous },
  context,
) {
  const metrics = [
      "screenPageViews",
      "totalUsers",
      "sessions",
      "sessionsPerUser",
      "averageSessionDuration",
      "ecommercePurchases",
      "averagePurchaseRevenue",
      "purchaseRevenue",
    ],
    state = previous ?? { index: 0, rows: [[], []] },
    i = state.index;
  if (
    !Number.isInteger(i) ||
    i < 0 ||
    i > 1 ||
    !Array.isArray(state.rows) ||
    state.rows.length !== 2
  )
    throw Error("Invalid report state");
  const result = await context.actions.call("google_analytics.run_report", {
      propertyId,
      dateRanges: [
        { startDate: i ? previousStart : recentStart, endDate: i ? previousEnd : recentEnd },
      ],
      dimensions: ["date"],
      metrics,
      keepEmptyRows: true,
      limit: 10000,
      offset: 0,
    }),
    r = result?.report;
  if (!r || !Array.isArray(r.rows)) throw Error("Invalid report");
  const count = r.rowCount ?? (r.rows.length === 0 ? 0 : null);
  if (!Number.isSafeInteger(count) || count !== r.rows.length || count > 8)
    throw Error("Incomplete or unexpected report");
  const rows = r.rows.map((x) => {
    if (
      !Array.isArray(x.dimensionValues) ||
      x.dimensionValues.length !== 1 ||
      !/^\d{8}$/.test(x.dimensionValues[0]) ||
      !Array.isArray(x.metricValues) ||
      x.metricValues.length !== 8 ||
      x.metricValues.some((v) => typeof v !== "string" || !Number.isFinite(Number(v)))
    )
      throw Error("Invalid report row");
    return { date: x.dimensionValues[0], values: x.metricValues.map(Number) };
  });
  const all = state.rows.map((x) => [...x]);
  all[i] = rows;
  return { state: { index: i + 1, rows: all }, more: i === 0 };
}

