export default function summary({ state, recentStart, recentEnd, previousStart, previousEnd }) {
  if (!state || state.index !== 2 || !Array.isArray(state.rows) || state.rows.length !== 2)
    throw Error("Reports are incomplete");
  const names = [
    "Page views",
    "Users (sum of daily users)",
    "Sessions",
    "Sessions per user (daily average)",
    "Average session duration seconds (daily average)",
    "Purchases",
    "Revenue per purchase (daily average)",
    "Purchase revenue",
  ];
  const sum = (rows) =>
    names.map((_, i) => {
      const n = rows.reduce((a, r) => a + r.values[i], 0);
      return [3, 4, 6].includes(i) && rows.length ? n / rows.length : n;
    });
  const a = sum(state.rows[0]),
    b = sum(state.rows[1]);
  return {
    facts: JSON.stringify({
      recent: { start: recentStart, end: recentEnd },
      previous: { start: previousStart, end: previousEnd },
      metrics: names.map((name, i) => ({
        name,
        recent: a[i],
        previous: b[i],
        changePercent: b[i] === 0 ? null : ((a[i] - b[i]) * 100) / b[i],
      })),
    }),
  };
}

